INSERT INTO snapshot_blobs (storage_key, seq, tenant_id, data) VALUES ('d1:t_demo/itm_inbox_0/8368c53bfb1e9ca2ddcef08a1562c04299a8451aa320d19c0786e5cf9f9133f9', 0, 't_demo', '<!doctype html><html><head><meta charset="utf-8"><title>Partnering with employers to widen access to specialty care</title><style>body{font:16px/1.6 Georgia,serif;max-width:720px;margin:32px auto;padding:0 16px;color:#222}.k{font:600 12px Arial,sans-serif;letter-spacing:.06em;text-transform:uppercase;color:#777}</style></head><body><article><div class="k">LinkedIn post</div><h1>Partnering with employers to widen access to specialty care</h1><p><em>Sanofi</em></p><p>Today we are announcing an agreement with a coalition of large US employers to offer selected medicines directly to covered employees, alongside a digital support program.</p><p>The arrangement bypasses traditional benefit intermediaries and sets a single transparent price for participating employers.</p></article></body></html>');
